sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float angle;
uniform float strength;
uniform float steps;
uniform float weight;
uniform float falloff;
uniform float palette;
layout(color) uniform half4 color1;
layout(color) uniform half4 color2;
layout(color) uniform half4 color3;
layout(color) uniform half4 color4;
layout(color) uniform half4 color5;
layout(color) uniform half4 color6;
uniform float alpha;
uniform float blend;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
float3 nearest(float3 x, float3 best, float3 c, inout float d) {
    float e = dot(x - c, x - c);
    if (e < d) {
        d = e;
        return c;
    }
    return best;
}
float3 quant(float3 x) {
    if (palette < 0.5) return float3(luma(x) > 0.5 ? 1.0 : 0.0);
    if (palette < 3.5) {
        float n = palette;
        return floor(clamp(x, 0.0, 1.0) * n + 0.5) / n;
    }
    if (palette < 5.5) {
        float n = palette - 2.0;
        return float3(floor(clamp(luma(x), 0.0, 1.0) * n + 0.5) / n);
    }
    if (palette > 8.5 && palette < 9.5) {
        float3 s = clamp(luma(x) + (x - luma(x)) * 2.5, 0.0, 1.0);
        return floor(s + 0.5);
    }
    float d = 100.0;
    float3 best = float3(0.0);
    if (palette < 6.5) {
        best = nearest(x, best, float3(0.0), d);
        best = nearest(x, best, float3(0.0, 0.67, 0.0), d);
        best = nearest(x, best, float3(0.67, 0.0, 0.0), d);
        return nearest(x, best, float3(0.67, 0.33, 0.0), d);
    }
    if (palette < 8.5) {
        best = nearest(x, best, palette < 7.5 ? float3(0.0) : float3(0.0, 0.0, 0.67), d);
        best = nearest(x, best, float3(0.33, 1.0, 1.0), d);
        best = nearest(x, best, float3(1.0, 0.33, 1.0), d);
        return nearest(x, best, float3(1.0), d);
    }
    float n = palette - 8.0;
    best = nearest(x, best, float3(color1.rgb), d);
    best = nearest(x, best, float3(color2.rgb), d);
    if (n > 2.5) best = nearest(x, best, float3(color3.rgb), d);
    if (n > 3.5) best = nearest(x, best, float3(color4.rgb), d);
    if (n > 4.5) best = nearest(x, best, float3(color5.rgb), d);
    if (n > 5.5) best = nearest(x, best, float3(color6.rgb), d);
    return best;
}
float3 colour(float2 p) {
    half4 c = image.eval(p);
    return c.a > 0.0 ? float3(c.rgb) / float(c.a) : float3(0.0);
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return half4(0.0);
    float a = radians(angle);
    float2 dir = float2(cos(a), sin(a));
    float reach = clamp(strength, 0.01, 1.0) * max(size.x, size.y);
    float n = clamp(floor(steps), 1.0, 200.0);
    float3 err = float3(0.0);
    for (int j = 0; j < 200; j++) {
        if (float(j) >= n) break;
        float far = n - float(j);
        float propagation = far <= 1.0 ? 1.0 : pow(1.0 - clamp(falloff, 0.0, 1.0), far - 1.0);
        float w = 1.0 + (weight - 1.0) * propagation;
        float3 x = colour(coord - dir * reach * far / n) + err * w;
        err = clamp(x - quant(x), -4.0, 4.0);
    }
    float3 base = float3(src.rgb) / float(src.a);
    float3 q = quant(base + err * weight);
    if (blend > 0.5 && blend < 1.5) q *= base;
    if (blend > 1.5) q = 1.0 - (1.0 - q) * (1.0 - base);
    float3 rgb = mix(base, q, clamp(alpha, 0.0, 1.0));
    return half4(half3(rgb * float(src.a)), src.a);
}
